# ============================================================
# SaleHop combined update -- everything since the last bundle:
#   1) Printable garage-sale sign with QR code
#   2) Admin visibility into failed signups/listings (Support section)
#   3) Contact form (saves to /admin + best-effort email)
#   4) Favoritable, routable physical-location ads (Goodwill, ReStore, etc.)
# ============================================================
#
# Run this from inside your salehop project folder (where package.json
# lives) -- same as every script before this one.
#
# Every file is delivered as Base64 and decoded with WriteAllBytes, and
# every folder is created with .NET's Directory.CreateDirectory -- the
# established, reliable pattern for special characters and "[id]" bracket
# folders on your machine. Verified byte-for-byte before this was sent to you.

# ---------- Safety check: are we actually in the right folder? ----------
# This stops the script before it writes anything if you're not sitting
# inside the real salehop project folder (the one with package.json and a
# hidden .git folder) -- running it from the wrong place (like your user
# home folder) was the cause of the "not a git repository" error before.
if (-not (Test-Path "package.json")) {
  Write-Host ""
  Write-Host "STOP: There's no package.json in this folder." -ForegroundColor Red
  Write-Host "You need to 'cd' into your actual salehop project folder first," -ForegroundColor Red
  Write-Host "then run this script again from there." -ForegroundColor Red
  Write-Host ""
  Write-Host "Current folder: $PWD" -ForegroundColor Yellow
  exit 1
}
if (-not (Test-Path ".git")) {
  Write-Host ""
  Write-Host "STOP: This folder has package.json but no .git folder," -ForegroundColor Red
  Write-Host "so it isn't connected to your GitHub/Vercel project." -ForegroundColor Red
  Write-Host "Make sure you're in the folder you originally cloned, not a copy." -ForegroundColor Red
  Write-Host ""
  Write-Host "Current folder: $PWD" -ForegroundColor Yellow
  exit 1
}
Write-Host "Found package.json and .git here -- this looks like the right folder." -ForegroundColor Cyan
Write-Host ""

Write-Host "Installing the qrcode package (used for the printable sign)..." -ForegroundColor Cyan
npm install qrcode

