$commit = Read-Host "Type Y and press Enter to commit and push these changes (or anything else to stop here)"
if ($commit -eq "Y" -or $commit -eq "y") {
  git add -A
  if ($LASTEXITCODE -ne 0) {
    Write-Host "git add failed -- see the error above. Nothing was committed or pushed." -ForegroundColor Red
    exit 1
  }

  git commit -m "Add printable signs, admin error/contact support, and favoritable physical-location ads"
  if ($LASTEXITCODE -ne 0) {
    Write-Host "git commit failed -- see the error above (this also happens if there was nothing new to commit). Nothing was pushed." -ForegroundColor Red
    exit 1
  }

  git push
  if ($LASTEXITCODE -ne 0) {
    Write-Host "git push failed -- see the error above. Your changes are committed locally but NOT on GitHub/Vercel yet." -ForegroundColor Red
    exit 1
  }

  Write-Host "Pushed successfully. Vercel will redeploy automatically -- check your Vercel dashboard in a minute or two." -ForegroundColor Green
} else {
  Write-Host "Stopped before committing. Your files are updated locally -- run git add -A, git commit, git push whenever you are ready." -ForegroundColor Yellow
}